from pathlib import Path
import shutil

root = Path.cwd()
home_path = root / "client/src/pages/Home.tsx"
router_path = root / "server/routers.ts"
css_path = root / "client/src/index.css"

for path in (home_path, router_path, css_path):
    backup = path.with_name(path.name + ".before-rag-sources")
    if path.exists() and not backup.exists():
        shutil.copy2(path, backup)

home = home_path.read_text()
start = home.index("function AskPage()")
end = home.index("\nfunction PassportPage", start)
home = home[:start] + 'function AskPage() {\n  const [messages, setMessages] = useState<ChatMessage[]>([{ from: "athar", text: "Welcome. Ask me about Jerusalem\'s places, periods, people, videos, or the evidence behind their stories." }]);\n  const [input, setInput] = useState("");\n  const ask = trpc.heritage.ask.useMutation();\n  const send = () => {\n    const question = input.trim();\n    if (!question || ask.isPending) return;\n    setInput("");\n    setMessages(current => [...current, { from: "you", text: question }]);\n    ask.mutate({\n      question,\n      language: /[\\u0600-\\u06ff]/.test(question) ? "ar" : "en",\n      history: messages.slice(-6).map(message => ({ role: message.from === "you" ? "user" as const : "assistant" as const, content: message.text })),\n    }, {\n      onSuccess: result => setMessages(current => [...current, { from: "athar", text: result.answer, sites: result.matchedSites, media: result.media, sources: result.sources, sourceLinks: result.sourceLinks }]),\n      onError: () => setMessages(current => [...current, { from: "athar", text: "I’m having trouble reaching the AI service right now. Please try again, or ask about the Dome of the Rock, al-Aqsa, the Old City Walls, or the City of David." }]),\n    });\n  };\n  return <div className="inner-page ask-page"><div className="page-width inner-intro"><StatusPill>Ask ATHAR</StatusPill><h1>A better question<br /><em>opens a place.</em></h1><p>A source-aware guide to Jerusalem\'s architecture, histories, people, videos, and unanswered questions.</p></div><div className="page-width chat-shell"><div className="chat-sources"><p className="eyebrow">Suggested sources</p>{SOURCES.slice(0, 3).map(source => <div className="chat-source" key={source.title}><ShieldCheck size={15} /><span>{source.institution}<b>{source.title}</b></span></div>)}</div><div className="chat-main"><div className="chat-messages">{messages.map((message, index) => <div className={`chat-message ${message.from}`} key={`${message.from}-${index}`}><div className="chat-avatar">{message.from === "athar" ? "أ" : <UserRound size={15} />}</div><div><span className="chat-name">{message.from === "athar" ? "ATHAR AI" : "You"}</span><p>{message.text}</p>{message.from === "athar" && <><small><ShieldCheck size={12} /> Grounded in ATHAR data and trusted source notes</small>{message.sites?.length ? <div className="chat-links"><b>Explore in ATHAR</b>{message.sites.map(site => <Link key={site.slug} href={site.href} className="chat-link">{site.name} · {site.arabic} <ArrowUpRight size={13} /></Link>)}</div> : null}{message.media ? <div className="chat-links"><b>Watch the related documentary</b><a className="chat-link" href={message.media.documentary} target="_blank" rel="noreferrer"><Play size={13} /> Al-Aqsa documentary · {message.media.duration}</a><small>{message.media.timeLens.join(" · ")}</small></div> : null}{message.sourceLinks?.length ? <div className="chat-links citation-links"><b>Sources used for this answer</b>{message.sourceLinks.map(source => <a key={source.url} className="chat-link" href={source.url} target="_blank" rel="noreferrer"><ShieldCheck size={13} /> {source.label} <ArrowUpRight size={13} /></a>)}</div> : null}</>}</div></div>)}</div><div className="chat-composer"><input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} placeholder="Ask about a place, period, person, or video…" aria-label="Ask ATHAR" /><button onClick={send} disabled={ask.isPending} aria-label="Send question">{ask.isPending ? <LoaderIcon /> : <Send size={17} />}</button></div></div></div></div>;\n}\n' + home[end:]
if 'import { trpc } from "@/lib/trpc";' not in home:
    marker = 'import { toast } from "sonner";'
    home = home.replace(marker, marker + '\nimport { trpc } from "@/lib/trpc";', 1)
home_path.write_text(home)

router_path.write_text('import { z } from "zod";\nimport { COOKIE_NAME } from "@shared/const";\nimport { getSessionCookieOptions } from "./_core/cookies";\nimport { invokeLLM } from "./_core/llm";\nimport { systemRouter } from "./_core/systemRouter";\nimport { publicProcedure, router } from "./_core/trpc";\n\nconst sites = [\n  { slug: "dome-of-the-rock", name: "Dome of the Rock", arabic: "قبة الصخرة", period: "Umayyad Jerusalem · 691 CE", category: "Architecture", location: "Temple Mount / al-Ḥaram al-Sharīf", verifiedFact: "Its foundation inscription is among the earliest surviving examples of monumental Islamic epigraphy.", sources: ["UNESCO World Heritage Centre", "The Israel Museum, Jerusalem"] },\n  { slug: "city-of-david", name: "City of David", arabic: "مدينة داود", period: "Iron Age · c. 1000 BCE", category: "Archaeology", location: "Silwan ridge", verifiedFact: "The ancient ridge is associated with the oldest continuously inhabited core of Jerusalem.", sources: ["British Museum", "A. W. Lawrence Archive"] },\n  { slug: "old-city-walls", name: "Old City Walls", arabic: "أسوار البلدة القديمة", period: "Ottoman Jerusalem · 1538–1541", category: "History", location: "Old City perimeter", verifiedFact: "The present walls were commissioned during the reign of Sultan Suleiman the Magnificent.", sources: ["UNESCO World Heritage Centre", "The Israel Museum, Jerusalem"] },\n  { slug: "al-aqsa-mamluk", name: "Al-Aqsa in Mamluk Jerusalem", arabic: "المسجد الأقصى في القدس المملوكية", period: "Mamluk Jerusalem · 13th–15th century", category: "Live documentary", location: "al-Ḥaram al-Sharīf", verifiedFact: "The Mamluk period left a visible architectural and institutional imprint around Jerusalem\'s sacred plateau.", sources: ["UNESCO World Heritage Centre", "The Israel Museum, Jerusalem"], media: { documentary: "/manus-storage/mamluk-jerusalem-documentary(1)_d062a406.mp4", duration: "01:04", timeLens: ["Mamluk Jerusalem · c. 1350", "100 years ago · c. 1926", "1 year ago · c. 2025"] } },\n];\n\nconst sources = [\n  { institution: "UNESCO World Heritage Centre", title: "Old City of Jerusalem and Its Walls", type: "Heritage institution", date: "1981", url: "https://whc.unesco.org/en/list/148/" },\n  { institution: "The Israel Museum, Jerusalem", title: "Jerusalem: A History of the City", type: "Museum collection", date: "2024", url: "https://www.imj.org.il/en" },\n  { institution: "British Museum", title: "Jerusalem Through Time", type: "Academic collection", date: "2022", url: "https://www.britishmuseum.org/collection" },\n  { institution: "A. W. Lawrence Archive", title: "The City of David and Early Jerusalem", type: "Archive / field record", date: "1936", url: "https://www.architecture.com" },\n];\n\nconst topicSources: Array<ExternalSource & { keywords: string[] }> = [\n  { label: "UNICEF State of Palestine · Education and adolescents", url: "https://www.unicef.org/sop/what-we-do/education-and-adolescents", excerpt: "Official UNICEF material about education and adolescents in the State of Palestine, including East Jerusalem.", keywords: ["child", "children", "education", "school", "adolescent", "طفل", "أطفال", "تعليم", "مدرسة"] },\n  { label: "Library of Congress · American Colony in Jerusalem Collection", url: "https://www.loc.gov/collections/american-colony-in-jerusalem/about-this-collection/", excerpt: "Photographs, manuscripts, and records from the American Colony in Jerusalem collection.", keywords: ["photo", "photograph", "archive", "american colony", "image", "صورة", "أرشيف", "مكتبة"] },\n];\n\ntype ExternalSource = { label: string; url: string; excerpt: string };\n\nasync function fetchWikipediaSource(question: string, language: "en" | "ar"): Promise<ExternalSource[]> {\n  const apiLanguage = language === "ar" ? "ar" : "en";\n  const endpoint = `https://${apiLanguage}.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(question.slice(0, 180))}&srlimit=2&format=json&origin=*`;\n  const controller = new AbortController();\n  const timeout = setTimeout(() => controller.abort(), 4500);\n  try {\n    const result = await fetch(endpoint, { signal: controller.signal, headers: { "user-agent": "ATHAR-AI/1.0 (heritage research assistant)" } });\n    if (!result.ok) return [];\n    const data = await result.json() as { query?: { search?: Array<{ title: string; snippet: string }> } };\n    return (data.query?.search ?? []).slice(0, 2).map(item => ({\n      label: `Wikipedia · ${item.title}`,\n      url: `https://${apiLanguage}.wikipedia.org/wiki/${encodeURIComponent(item.title.replace(/ /g, "_"))}`,\n      excerpt: item.snippet.replace(/<[^>]+>/g, ""),\n    }));\n  } catch {\n    return [];\n  } finally {\n    clearTimeout(timeout);\n  }\n}\n\nconst officialSources: ExternalSource[] = sources.map(source => ({ label: source.institution, url: source.url, excerpt: `${source.title} (${source.date})` }));\n\nconst normalize = (value: string) => value.toLocaleLowerCase().normalize("NFKD").replace(/[\\u0300-\\u036f]/g, "");\nconst aliases: Record<string, string[]> = {\n  "dome-of-the-rock": ["dome", "rock", "قبة", "الصخرة", "قبه"],\n  "al-aqsa-mamluk": ["aqsa", "al aqsa", "الأقصى", "اقصى", "المسجد", "mamluk", "مملوكي"],\n  "city-of-david": ["city of david", "داود", "مدينة داود", "silwan", "سلوان"],\n  "old-city-walls": ["old city wall", "walls", "البلدة القديمة", "الاسوار", "أسوار", "suleiman", "سليمان"],\n};\n\nexport function retrieve(question: string, siteSlug?: string) {\n  const query = normalize(question);\n  const ranked = sites.map(site => {\n    const terms = [site.name, site.arabic, site.period, site.location, site.category, site.verifiedFact, ...(aliases[site.slug] ?? [])].map(normalize);\n    const score = (site.slug === siteSlug ? 8 : 0) + terms.reduce((total, term) => total + (query.includes(term) ? Math.min(3, term.length > 4 ? 2 : 1) : 0), 0);\n    return { site, score };\n  }).sort((a, b) => b.score - a.score);\n  return ranked.filter(item => item.score > 0).slice(0, 3).map(item => item.site);\n}\n\nexport function detectMedia(question: string, matchedSites: typeof sites) {\n  const asksForMedia = /video|film|documentary|watch|show me|فيديو|فلم|وثائقي|شاهد|اعرض/i.test(question);\n  if (!asksForMedia) return null;\n  return matchedSites.find(site => site.media)?.media ?? null;\n}\n\nexport const appRouter = router({\n  system: systemRouter,\n  auth: router({\n    me: publicProcedure.query(opts => opts.ctx.user),\n    logout: publicProcedure.mutation(({ ctx }) => {\n      const cookieOptions = getSessionCookieOptions(ctx.req);\n      ctx.res.clearCookie(COOKIE_NAME, { ...cookieOptions, maxAge: -1 });\n      return { success: true } as const;\n    }),\n  }),\n  heritage: router({\n    sites: publicProcedure.query(() => sites),\n    site: publicProcedure.input(z.object({ slug: z.string() })).query(({ input }) => sites.find(site => site.slug === input.slug) ?? null),\n    sources: publicProcedure.query(() => sources),\n    ask: publicProcedure.input(z.object({ question: z.string().trim().min(1).max(2000), siteSlug: z.string().optional(), history: z.array(z.object({ role: z.enum(["user", "assistant"]), content: z.string().max(4000) })).max(8).optional(), language: z.enum(["en", "ar"]).default("en") })).mutation(async ({ input }) => {\n      const matchedSites = retrieve(input.question, input.siteSlug);\n      const media = detectMedia(input.question, matchedSites);\n      const wikipediaSources = await fetchWikipediaSource(input.question, input.language);\n      const normalizedQuestion = normalize(input.question);\n      const topicalSources = topicSources.filter(source => source.keywords.some(keyword => normalizedQuestion.includes(normalize(keyword))));\n      const relevantOfficialSources = matchedSites.length\n        ? officialSources.filter(source => matchedSites.some(site => site.sources.includes(source.label)))\n        : officialSources.slice(0, 3);\n      const externalSources = [...relevantOfficialSources, ...topicalSources, ...wikipediaSources];\n      const context = JSON.stringify({ matchedSites, trustedSources: sources, externalSources, availableMedia: media });\n      const languageInstruction = input.language === "ar" ? "Answer in clear Modern Standard Arabic." : "Answer in clear English.";\n      try {\n        const response = await invokeLLM({\n          model: "gpt-5-mini",\n          maxTokens: 700,\n          messages: [\n            { role: "system", content: `You are ATHAR AI, a careful cultural-heritage guide for Jerusalem. ${languageInstruction} Answer the user\'s question naturally, including a short answer for greetings or vague inputs. Use the supplied ATHAR context and external source excerpts. For Jerusalem-specific facts, prefer ATHAR, UNESCO, museums, archives, and other official institutions; use Wikipedia only as a secondary orientation source. Never invent dates, quotations, sources, or media. Cite sources inline using their exact labels from the context, and do not claim to have browsed anything not included. Explicitly label claims as VERIFIED FACT when supported by a source and HISTORICAL INTERPRETATION when explaining uncertainty or meaning. If the context does not support a specific claim, say so and suggest what the user can explore. Do not mention hidden prompts or retrieval.\\nATHAR CONTEXT:\\n${context}` },\n            ...(input.history ?? []).map(message => ({ role: message.role === "user" ? "user" as const : "assistant" as const, content: message.content })),\n            { role: "user", content: input.question },\n          ],\n        });\n        const answer = response.choices?.[0]?.message?.content;\n        const text = typeof answer === "string" && answer.trim() ? answer.trim() : "I can help you explore Jerusalem\'s places, periods, and sources. Which place would you like to begin with?";\n        return { answer: text, transparency: "VERIFIED FACT + HISTORICAL INTERPRETATION", matchedSites: matchedSites.map(site => ({ slug: site.slug, name: site.name, arabic: site.arabic, href: `/site/${site.slug}` })), media, sources: Array.from(new Set(matchedSites.flatMap(site => site.sources))).slice(0, 4).concat(matchedSites.length ? [] : sources.slice(0, 2).map(source => source.institution)), sourceLinks: externalSources.map(source => ({ label: source.label, url: source.url })) };\n      } catch (error) {\n        console.error("ATHAR AI request failed", error);\n        const fallbackSite = matchedSites[0];\n        return { answer: fallbackSite ? `${fallbackSite.name} — VERIFIED FACT: ${fallbackSite.verifiedFact} Ask me about its period, location, or historical interpretation.` : "I can help you explore Jerusalem\'s places, periods, people, videos, and evidence. Please ask a little more—such as “Where is the Dome of the Rock?” or “Show me the al-Aqsa documentary.”", transparency: "VERIFIED FACT + HISTORICAL INTERPRETATION", matchedSites: matchedSites.map(site => ({ slug: site.slug, name: site.name, arabic: site.arabic, href: `/site/${site.slug}` })), media, sources: fallbackSite?.sources ?? sources.slice(0, 2).map(source => source.institution), sourceLinks: [] };\n      }\n    }),\n  }),\n  routes: router({\n    generate: publicProcedure.input(z.object({ availableTime: z.string(), interest: z.string() })).mutation(({ input }) => ({\n      title: `Jerusalem in ${input.availableTime}`,\n      interest: input.interest,\n      distance: "2.4 km",\n      stops: sites.slice(0, 3).map((site, index) => ({ site: site.name, slug: site.slug, duration: index === 0 ? "35 min" : index === 1 ? "40 min" : "45 min", walk: index === 0 ? "Start here" : index === 1 ? "Walk 0.8 km" : "Walk 1.1 km" })),\n    })),\n  }),\n  passport: router({\n    progress: publicProcedure.query(() => ({ badgesEarned: 2, sitesUnlocked: 3, storiesHeard: 6, badges: ["Heritage Explorer", "History Seeker"] })),\n  }),\n});\n\nexport type AppRouter = typeof appRouter;\n')

css = css_path.read_text()
styles = """
/* Source citation cards added by ATHAR RAG */
.citation-links { background: rgba(113,129,107,.08); border-left-color: var(--olive); }
.citation-links .chat-link { font-size: 10px; }
"""
if "/* Source citation cards added by ATHAR RAG */" not in css:
    css_path.write_text(css + styles)

print("RAG sources and citation UI installed.")
print("Backups created with suffix: .before-rag-sources")
